from pathlib import Path

PERSISTENCE = Path("mvp/autotrade_mvp/_persistence_impl.py")
CHECKPOINT = Path("mvp/autotrade_mvp/simulation_runtime_checkpoint.py")
WORKFLOW = Path(".github/workflows/patch-zero-scoped-outbox.yml")
SELF = Path(__file__)

persistence = PERSISTENCE.read_text(encoding="utf-8")
old_count = '''    def pending_outbox_count(self) -> int:\n        """Return the complete durable undelivered outbox cardinality.\n\n        This read-only count is intentionally unbounded so recovery/performance\n        qualification cannot mistake a page limit for the actual reconnect\n        backlog.\n        """\n        with self._connect() as connection:\n            row = connection.execute(\n                "SELECT COUNT(*) AS pending_count FROM outbox WHERE delivered_at IS NULL"\n            ).fetchone()\n        if row is None:\n            raise RuntimeError("pending outbox count query returned no row")\n        return int(row["pending_count"])\n\n    def pending_outbox(self, *, limit: int = 100) -> list[dict[str, Any]]:\n        if not isinstance(limit, int) or limit < 1 or limit > 1000:\n            raise ValueError("limit must be between 1 and 1000")\n        with self._connect() as connection:\n            rows = connection.execute(\n                """\n                SELECT\n                    outbox.outbox_id,\n                    outbox.event_id,\n                    outbox.topic,\n                    outbox.payload_json AS outbox_payload_json,\n                    outbox.created_at,\n                    outbox.envelope_hash,\n                    events.event_type,\n                    events.aggregate_type,\n                    events.aggregate_id,\n                    events.aggregate_version,\n                    events.payload_json AS event_payload_json,\n                    events.payload_hash,\n                    events.committed_at,\n                    events.envelope_json AS event_envelope_json,\n                    events.envelope_hash AS event_envelope_hash\n                FROM outbox\n                JOIN events ON events.event_id = outbox.event_id\n                WHERE outbox.delivered_at IS NULL\n                ORDER BY outbox.created_at, outbox.outbox_id\n                LIMIT ?\n                """,\n                (limit,),\n            ).fetchall()\n'''
new_count = '''    @staticmethod\n    def _outbox_aggregate_scope(\n        aggregate_types: tuple[str, ...] | None,\n    ) -> tuple[str, ...] | None:\n        if aggregate_types is None:\n            return None\n        if type(aggregate_types) is not tuple or not aggregate_types:\n            raise ValueError("aggregate_types must be a non-empty exact tuple or None")\n        values: list[str] = []\n        for value in aggregate_types:\n            if type(value) is not str or not value or value != value.strip():\n                raise ValueError("aggregate_types must contain canonical non-empty text")\n            values.append(value)\n        if len(set(values)) != len(values):\n            raise ValueError("aggregate_types must not contain duplicates")\n        return tuple(values)\n\n    def pending_outbox_count(\n        self,\n        *,\n        aggregate_types: tuple[str, ...] | None = None,\n    ) -> int:\n        """Return durable undelivered cardinality, optionally by event authority scope."""\n        scope = self._outbox_aggregate_scope(aggregate_types)\n        with self._connect() as connection:\n            if scope is None:\n                row = connection.execute(\n                    "SELECT COUNT(*) AS pending_count FROM outbox WHERE delivered_at IS NULL"\n                ).fetchone()\n            else:\n                placeholders = ",".join("?" for _ in scope)\n                row = connection.execute(\n                    "SELECT COUNT(*) AS pending_count "\n                    "FROM outbox JOIN events ON events.event_id = outbox.event_id "\n                    "WHERE outbox.delivered_at IS NULL "\n                    f"AND events.aggregate_type IN ({placeholders})",\n                    scope,\n                ).fetchone()\n        if row is None:\n            raise RuntimeError("pending outbox count query returned no row")\n        return int(row["pending_count"])\n\n    def pending_outbox(\n        self,\n        *,\n        limit: int = 100,\n        aggregate_types: tuple[str, ...] | None = None,\n    ) -> list[dict[str, Any]]:\n        if not isinstance(limit, int) or limit < 1 or limit > 1000:\n            raise ValueError("limit must be between 1 and 1000")\n        scope = self._outbox_aggregate_scope(aggregate_types)\n        where = "outbox.delivered_at IS NULL"\n        parameters: list[object] = []\n        if scope is not None:\n            placeholders = ",".join("?" for _ in scope)\n            where += f" AND events.aggregate_type IN ({placeholders})"\n            parameters.extend(scope)\n        parameters.append(limit)\n        with self._connect() as connection:\n            rows = connection.execute(\n                f"""\n                SELECT\n                    outbox.outbox_id,\n                    outbox.event_id,\n                    outbox.topic,\n                    outbox.payload_json AS outbox_payload_json,\n                    outbox.created_at,\n                    outbox.envelope_hash,\n                    events.event_type,\n                    events.aggregate_type,\n                    events.aggregate_id,\n                    events.aggregate_version,\n                    events.payload_json AS event_payload_json,\n                    events.payload_hash,\n                    events.committed_at,\n                    events.envelope_json AS event_envelope_json,\n                    events.envelope_hash AS event_envelope_hash\n                FROM outbox\n                JOIN events ON events.event_id = outbox.event_id\n                WHERE {where}\n                ORDER BY outbox.created_at, outbox.outbox_id\n                LIMIT ?\n                """,\n                tuple(parameters),\n            ).fetchall()\n'''
if persistence.count(old_count) != 1:
    raise SystemExit("exact pending-outbox source preimage not found once")
persistence = persistence.replace(old_count, new_count)
PERSISTENCE.write_text(persistence, encoding="utf-8")

checkpoint = CHECKPOINT.read_text(encoding="utf-8")
old_checkpoint = '''def _autonomous_owned_pending_publications(\n    store: JournalStore,\n    *,\n    run_id: str,\n) -> tuple[dict[str, object], ...]:\n    pending = JournalStore.pending_outbox(store, limit=1000)\n    count = JournalStore.pending_outbox_count(store)\n    if len(pending) == 1000 and count > len(pending):\n        raise AutonomousRuntimeCheckpointError(\n            "runtime checkpoint publication ownership scan exceeded bounded outbox window"\n        )\n    if len(pending) != count:\n        raise AutonomousRuntimeCheckpointError(\n            "runtime checkpoint pending outbox changed during ownership preflight"\n        )\n    return tuple(\n        item\n        for item in pending\n        if _autonomous_publication_owned(item, run_id=run_id)\n    )\n'''
new_checkpoint = '''def _autonomous_owned_pending_publications(\n    store: JournalStore,\n    *,\n    run_id: str,\n) -> tuple[dict[str, object], ...]:\n    candidate_types = (\n        "canonical_autonomous_simulation",\n        *_COMPONENT_AGGREGATE_TYPES,\n    )\n    pending = JournalStore.pending_outbox(\n        store,\n        limit=1000,\n        aggregate_types=candidate_types,\n    )\n    count = JournalStore.pending_outbox_count(\n        store,\n        aggregate_types=candidate_types,\n    )\n    if len(pending) == 1000 and count > len(pending):\n        raise AutonomousRuntimeCheckpointError(\n            "runtime checkpoint ZERO-candidate publication scan exceeded bounded outbox window"\n        )\n    if len(pending) != count:\n        raise AutonomousRuntimeCheckpointError(\n            "runtime checkpoint ZERO-candidate outbox changed during ownership preflight"\n        )\n    return tuple(\n        item\n        for item in pending\n        if _autonomous_publication_owned(item, run_id=run_id)\n    )\n'''
if checkpoint.count(old_checkpoint) != 1:
    raise SystemExit("exact ZERO ownership source preimage not found once")
checkpoint = checkpoint.replace(old_checkpoint, new_checkpoint)
CHECKPOINT.write_text(checkpoint, encoding="utf-8")

# The running workflow has already loaded these temporary mutation helpers.
# Remove them from the durable product delta before committing the implementation.
SELF.unlink()
WORKFLOW.unlink()
